// Managed event record page (moderators): create / edit / archive / delete.
// Publishing lives on the event's Publish to list. id = "new" creates an event.
import React, { useEffect, useState } from 'react';
import { Pressable, Text, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { router, Stack, useLocalSearchParams } from 'expo-router';
import { BackChevron, Button, EmptyState, ErrorText, Field, FieldGrid, Page, SectionCard, Segmented, StatusPill, styles } from '../../../components/ui';
import { useConfirmDelete } from '../../../components/confirm-sheet';
import { NotFound, useCanModerate } from '../../../components/mod';
import { ActionRow, CoverBand, EntityTitle } from '../../../components/record-chrome';
import { PublishToList } from '../../../components/publish-to';
import { deleteEvent, eventUnlistedToken, getEventForEdit, listGroups, saveEvent, setEventArchived } from '../../../lib/api';
import { EventApplications } from '../../../components/event-applications';
import { PublishLinkLine, useCopiedShare } from '../../../components/publish-to';
import { eventVisibility, eventVisibilityHelp, eventVisibilityLabel, EVENT_VISIBILITY_OPTIONS, unlistedEventPath } from '../../../lib/event-visibility';
import { copyPublicPath } from '../../../lib/share-link';
import { publicAppUrl } from '../../../lib/public-url';
import { flash } from '../../../lib/flash';
import { DeleteEventSheet } from '../../../components/delete-event-sheet';
import { CLUB_GROUP_SLUG } from '../../../lib/group-views';
import { fmtDate, parseLocal, toLocalInput } from '../../../lib/format';
import { OwnerFace } from '../../../components/owner-face';
import { useOwnerProfile } from '../../../lib/owner-label';
import { colors, fonts, fs } from '../../../lib/theme';
import type { ClubEvent, ClubGroup, EventVisibility } from '../../../lib/types';

type Form = { title: string; description: string; starts: string; ends: string; venue_name: string; venue_address: string; group_id: string; visibility: EventVisibility };
const blank: Form = { title: '', description: '', starts: '', ends: '', venue_name: '', venue_address: '', group_id: '', visibility: 'public' };
const toForm = (e: ClubEvent): Form => ({ title: e.title, description: e.description, starts: toLocalInput(e.starts_at), ends: toLocalInput(e.ends_at), venue_name: e.venue_name ?? '', venue_address: e.venue_address ?? '', group_id: e.group_id ?? '', visibility: eventVisibility(e.visibility) });

function GroupPicker({ groups, value, onChange }: { groups: ClubGroup[]; value: string; onChange: (id: string) => void }) {
  const choices = groups.filter((g) => !g.archived || g.id === value);
  if (!choices.length) return null;
  return (
    <View style={{ marginBottom: 14, gap: 6 }}>
      <Text style={styles.label}>Group</Text>
      {choices.map((g) => {
        const on = g.id === value;
        return (
          <Pressable key={g.id} onPress={() => onChange(g.id)} accessibilityRole="radio" accessibilityState={{ selected: on }}
            style={{ flexDirection: 'row', alignItems: 'center', gap: 8, paddingVertical: 8, paddingHorizontal: 10, borderWidth: 1, borderColor: on ? colors.navy : colors.line, borderRadius: 6, backgroundColor: on ? colors.navySoft : '#fff' }}>
            <Ionicons name={on ? 'radio-button-on' : 'radio-button-off'} size={16} color={colors.navy} />
            <Text style={{ flex: 1, fontFamily: on ? fonts.sansMedium : fonts.sans, fontSize: fs(14), color: colors.ink }}>{g.name}</Text>
          </Pressable>
        );
      })}
    </View>
  );
}
export default function ManageEvent() {
  const params = useLocalSearchParams<{ id: string; group?: string }>();
  const id = Array.isArray(params.id) ? params.id[0] : params.id;
  const presetGroup = Array.isArray(params.group) ? params.group[0] : params.group;
  const isNew = id === 'new';
  const { ready, ok } = useCanModerate();
  const [ev, setEv] = useState<ClubEvent | null | undefined>(isNew ? null : undefined);
  const [form, setForm] = useState<Form>(blank);
  const [err, setErr] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const removeSheet = useConfirmDelete();
  const [groups, setGroups] = useState<ClubGroup[]>([]);
  const [token, setToken] = useState<string | null>(null);
  const owner = useOwnerProfile(ev?.owner_id, !!ev);
  const { copy, title: copyTitle } = useCopiedShare(setErr);

  const reload = async () => {
    const e = await getEventForEdit(id!);
    setEv(e);
    if (e) setForm(toForm(e));
    setToken(e && eventVisibility(e.visibility) === 'hidden' ? await eventUnlistedToken(e.id) : null);
  };
  useEffect(() => { if (ok && !isNew) reload().catch((e) => setErr(e.message)); }, [ok, id]);
  useEffect(() => {
    if (!ok) return;
    listGroups(true).then(setGroups).catch(() => setGroups([]));
  }, [ok]);
  useEffect(() => {
    if (!isNew) return;
    setForm((current) => {
      if (current.group_id) return current;
      const preset = presetGroup && groups.some((g) => g.id === presetGroup) ? presetGroup : '';
      const seed = groups.find((g) => g.slug === CLUB_GROUP_SLUG && !g.archived) ?? groups.find((g) => !g.archived);
      const next = preset || seed?.id || '';
      return next ? { ...current, group_id: next } : current;
    });
  }, [isNew, presetGroup, groups]);

  if (!ready) return <View style={{ flex: 1 }} />;
  if (!ok) return <NotFound />;
  if (!isNew && ev === null) return <Page><BackChevron fallback="/events" /><EmptyState title="Event not found" /></Page>;

  const run = async (label: string, fn: () => Promise<string | void>) => {
    setBusy(label); setErr(null); setNote(null);
    try { const n = await fn(); if (n) setNote(n); } catch (e: any) { setErr(e.message); } finally { setBusy(null); }
  };
  const save = () => run('save', async () => {
    if (!form.title.trim()) throw new Error('Title is required.');
    const starts_at = parseLocal(form.starts);
    if (!starts_at) throw new Error('Start time is required.');
    const ends_at = parseLocal(form.ends);
    if (ends_at && ends_at <= starts_at) throw new Error('End must be after start.');
    if (groups.length && !form.group_id) throw new Error('Choose a group.');
    if (form.visibility === 'hidden' && ev?.meetup_publish_status === 'PUBLISHED') throw new Error('Cancel this event on Meetup before hiding it.');
    const input = { title: form.title.trim(), description: form.description.trim(), starts_at, ends_at, venue_name: form.venue_name.trim() || null, venue_address: form.venue_address.trim() || null, visibility: form.visibility, ...(form.group_id ? { group_id: form.group_id } : {}) };
    const newId = await saveEvent(input, isNew ? undefined : id);
    if (isNew) { router.replace(`/events/manage/${newId}`); return; }
    await reload();
    if (form.visibility === 'hidden') return 'Saved. This event is hidden. Share the unlisted link. It stays off the web directory and Meetup.';
    if (form.visibility === 'private') return 'Saved. Publish the teaser when you want it searchable. People apply, and you approve them here.';
    return 'Saved. Meetup and the public page stay as they are until you publish.';
  });
  const archive = () => run('archive', async () => {
    if (!ev) return;
    await setEventArchived(ev.id, !ev.archived); await reload();
    return ev.archived ? 'Restored.' : 'Archived — hidden from members.';
  });
  const remove = (options: { unlinkMeetup: boolean }) => {
    if (!ev) return;
    setErr(null);
    removeSheet.run(async () => {
      await deleteEvent(ev.id, options);
      flash('Event deleted');
      router.replace('/events');
    });
  };

  const set = (k: keyof Form) => (t: string) => setForm({ ...form, [k]: t });
  return (
    <Page>
      <Stack.Screen options={{ title: isNew ? 'New event' : ev?.title ?? 'Event', headerShown: false }} />
      <BackChevron fallback={isNew || !id ? '/events' : `/events/${id}`} />
      {isNew ? <EntityTitle title="New event" meta="Create a club event. Nothing goes to Meetup or the public page until you publish it." />
        : ev ? <>
          <CoverBand url={ev.image_url} />
          <EntityTitle title={ev.title} meta={fmtDate(ev.starts_at)} pills={<><StatusPill label={ev.archived ? 'Archived' : 'Active'} tone={ev.archived ? 'default' : 'success'} /><StatusPill label={eventVisibilityLabel(ev.visibility)} tone={eventVisibility(ev.visibility) === 'hidden' ? 'warning' : eventVisibility(ev.visibility) === 'private' ? 'info' : 'default'} /></>} />
          <ActionRow>
            <Button small variant="neutral" icon="eye-outline" title="View" onPress={() => router.push(`/events/${ev.id}`)} />
            <Button small variant="neutral" icon="archive-outline" title={ev.archived ? 'Unarchive' : 'Archive'} loading={busy === 'archive'} onPress={archive} />
            <Button small variant="danger" icon="trash-outline" title="Delete" onPress={removeSheet.ask} />
          </ActionRow>
          <FieldGrid fields={[['Starts', fmtDate(ev.starts_at)], ['Ends', fmtDate(ev.ends_at)], ['Venue', ev.venue_name ?? '—'], ['Group', groups.find((g) => g.id === (form.group_id || ev.group_id))?.name ?? '—'], ...(owner ? [['Owner', <OwnerFace profile={owner} />] as [string, React.ReactNode]] : [])]} />
        </> : null}
      <ErrorText>{err}</ErrorText>
      {note ? <Text style={[styles.muted, { fontSize: fs(13) }]}>{note}</Text> : null}
      <SectionCard title={isNew ? 'Details' : 'Edit details'}>
        <Field label="Title" value={form.title} onChangeText={set('title')} maxLength={120} />
        <Field label="Description" value={form.description} onChangeText={set('description')} multiline />
        <Field label="Starts" help="YYYY-MM-DD HH:mm, your local time" placeholder="2026-11-05 19:00" value={form.starts} onChangeText={set('starts')} />
        <Field label="Ends" help="Optional — defaults to 2 hours on Meetup" placeholder="2026-11-05 21:00" value={form.ends} onChangeText={set('ends')} />
        <Field label="Venue" value={form.venue_name} onChangeText={set('venue_name')} />
        <Field label="Address" value={form.venue_address} onChangeText={set('venue_address')} />
        <GroupPicker groups={groups} value={form.group_id} onChange={(groupId) => setForm({ ...form, group_id: groupId })} />
        <View style={{ marginBottom: 14, gap: 6 }}>
          <Text style={styles.label}>Visibility</Text>
          <Segmented value={form.visibility} options={EVENT_VISIBILITY_OPTIONS} onChange={(visibility) => setForm({ ...form, visibility })} />
          <Text style={styles.muted}>{eventVisibilityHelp(form.visibility)}</Text>
        </View>
        <View style={{ flexDirection: 'row', gap: 8 }}>
          <Button title={isNew ? 'Create event' : 'Save'} onPress={save} loading={busy === 'save'} />
          <Button variant="neutral" title="Cancel" onPress={() => (router.canGoBack() ? router.back() : router.replace('/events'))} />
        </View>
      </SectionCard>
      {ev && eventVisibility(ev.visibility) === 'hidden' ? (
        <SectionCard title="Unlisted link">
          <Text style={styles.body}>Anyone with this link can open the teaser. They sign up to RSVP. Plus-ones aren’t available. The link is not listed in directories.</Text>
          {token ? <PublishLinkLine>{publicAppUrl(unlistedEventPath(token))}</PublishLinkLine> : <Text style={[styles.muted, { marginTop: 8 }]}>Save the event to create the link.</Text>}
          {token ? <View style={{ marginTop: 12, alignSelf: 'flex-start' }}><Button small variant="neutral" icon="link-outline" title={copyTitle} onPress={() => { void copy(() => copyPublicPath(unlistedEventPath(token))); }} /></View> : null}
        </SectionCard>
      ) : null}
      {ev && eventVisibility(ev.visibility) === 'private' ? <EventApplications eventId={ev.id} /> : null}
      {ev ? <PublishToList event={ev} /> : null}
      {ev ? <DeleteEventSheet visible={removeSheet.open} meetupLinked={!!ev.meetup_id} busy={removeSheet.busy} error={removeSheet.error}
        onCancel={removeSheet.cancel}
        onConfirm={remove} /> : null}
    </Page>
  );
}
